entry() { mkdir -p "$d"; printf '{"v":1,"sessionId":"%s","agent":"coder","cwd":"%s","transcriptPath":"%s","pid":%s,"startedAt":"%s","recordedAt":1}' "$sid" "$HOME" "$HOME/.claude/projects/p/$sid.jsonl" "$$" "$now" > "$d/$sid.json"; }
case "$FAKE_MODE" in
  claim) mkdir -p "$d"; printf '{"pid": %s, "procStart": null, "at": "2026-01-01T00:00:00Z", "kind": "terminal"}' "$PPID" > "$d/s-1.claim" ;;
  claim-other) mkdir -p "$d"; printf '{"pid": 99999, "procStart": null, "at": "2026-01-01T00:00:00Z", "kind": "terminal"}' > "$d/s-2.claim" ;;
  registry|registry-crash) entry ;;
  taken) entry; sleep 1; touch "$d/$sid.taken" ;;
  idle) entry; exec sleep 8 ;;
  idle-busy) entry; sleep 3 ;;
  exit3) exit 3 ;;
  term) kill -TERM $$; sleep 5 ;;
esac
[ "$FAKE_MODE" = registry-crash ] && exit 1
exit ${FAKE_EXIT:-0}
